class DSU {
private:
    vector<int> parent, size;
    int n;

public:
    DSU(int n) : n(n), parent(n + 1), size(n + 1, 1) {
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
        }
    }

    int find(int node) {
        if (parent[node] != node) {
            parent[node] = find(parent[node]);
        }
        return parent[node];
    }

    int unionSets(int u, int v) {
        int pu = find(u), pv = find(v);
        if (pu == pv) {
            return 0;
        }
        if (size[pu] < size[pv]) {
            swap(pu, pv);
        }
        size[pu] += size[pv];
        parent[pv] = pu;
        n--;
        return 1;
    }

    bool isConnected() {
        return n == 1;
    }
};

class Solution {
public:
    int maxNumEdgesToRemove(int n, vector<vector<int>>& edges) {
        DSU alice(n), bob(n);
        int cnt = 0;

        for (auto& edge : edges) {
            if (edge[0] == 3) {
                cnt += (alice.unionSets(edge[1], edge[2]) | bob.unionSets(edge[1], edge[2]));
            }
        }

        for (auto& edge : edges) {
            if (edge[0] == 1) {
                cnt += alice.unionSets(edge[1], edge[2]);
            } else if (edge[0] == 2) {
                cnt += bob.unionSets(edge[1], edge[2]);
            }
        }

        if (alice.isConnected() && bob.isConnected()) {
            return edges.size() - cnt;
        }
        return -1;
    }
};
